import{_ as e,o as a,c as s,a3 as i}from"./chunks/framework.CrOIO8K-.js";const g=JSON.parse('{"title":"IEC61850 批读回退与索引性能修复","description":"","frontmatter":{},"headers":[],"relativePath":"changelog/iec61850/27-iec61850-batch-read-projection-performance-fix.md","filePath":"changelog/iec61850/27-iec61850-batch-read-projection-performance-fix.md","lastUpdated":1788910228000}'),l={name:"changelog/iec61850/27-iec61850-batch-read-projection-performance-fix.md"};function d(n,t,r,c,o,p){return a(),s("div",null,[...t[0]||(t[0]=[i(`<h1 id="iec61850-批读回退与索引性能修复" tabindex="-1">IEC61850 批读回退与索引性能修复 <a class="header-anchor" href="#iec61850-批读回退与索引性能修复" aria-label="Permalink to &quot;IEC61850 批读回退与索引性能修复&quot;">​</a></h1><p>日期：2026-09-09</p><h2 id="排查证据" tabindex="-1">排查证据 <a class="header-anchor" href="#排查证据" aria-label="Permalink to &quot;排查证据&quot;">​</a></h2><p>现场日志 <code>log/iec61850.log</code> 的 2026-09-09 07:10:13 批读记录：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>requested=4542, datasets=34, covered=4055, fallback=487,</span></span>
<span class="line"><span>failed=19, requests=521, elapsed=21251.56ms</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>DataSet 优先读取仍在执行。用当天的 <code>127.0.0.1:3782</code> 缓存模型和 <code>data/device/IEC61850-SVR/KG_BAMS.icd</code> 启动独立临时端口服务，复现了完全相同的 487 个缺失点：</p><ul><li>425 个 DataSet 成员报 <code>projection mismatch: model=1, values=3</code>。 在线发现把状态对象的 <code>q/t</code> 固定推断为 MX，而主值 <code>stVal</code> 属于 ST。 按 ST 投影时只剩主值，实际响应包含主值、品质和时标三个字段，整个成员被拒绝。</li><li>62 个系统状态测点未配置在 DataSet 中，例如 LLN0 的 Health/Mod，必须兼容补读。</li><li>旧目录构建对每个 FCDA 扫描全部模型叶子。本地离线测量构建耗时 9.47 秒，规划另耗时 0.34 秒。</li><li>隔离服务上，34 个 DataSet 的原生读取及解码合计约 0.43 秒。</li></ul><p>进一步核对主值发现：名称目录返回 <code>q/stVal/t</code> 字母序，而实际结构返回 <code>stVal/q/t</code>。 仅修正 FC 会使主值和品质错位，不能作为完整修复。</p><h2 id="实现" tabindex="-1">实现 <a class="header-anchor" href="#实现" aria-label="Permalink to &quot;实现&quot;">​</a></h2><ol><li>在线 DA 目录优先使用 <code>getDataDirectoryFC</code>，保留设备返回的真实 FC。</li><li>按 LN/FC 查询并缓存变量规格，恢复 DA/BDA 原始字段顺序和实际 MMS 类型。 查询不按测点重复，缓存不持有原生指针；规格使用后统一释放。</li><li>规格不可用的在线 DO 标记 <code>unverifiedFCs</code> 并持久化，禁止猜测结构成员顺序； 精确标量成员仍可批读，结构成员保留单点兼容回退。</li><li>一次遍历建立叶子与祖先引用索引，成员投影改为查表；规划改用候选覆盖集合求交。</li><li>批读日志增加 planning、dataset_read、fallback_read 耗时及 uncovered、covered_but_failed 分类。 DataSet 成员错误改为 WARNING，默认文件日志可见。</li></ol><h2 id="验证" tabindex="-1">验证 <a class="header-anchor" href="#验证" aria-label="Permalink to &quot;验证&quot;">​</a></h2><p>同一 ICD 的隔离服务，重新在线发现后读取 4542 个遥测/遥信点：</p><table tabindex="0"><thead><tr><th>指标</th><th style="text-align:right;">首次读取</th><th style="text-align:right;">索引缓存命中</th></tr></thead><tbody><tr><td>总耗时</td><td style="text-align:right;">471.74 ms</td><td style="text-align:right;">380.21 ms</td></tr><tr><td>规划（含索引）</td><td style="text-align:right;">96.06 ms</td><td style="text-align:right;">3.39 ms</td></tr><tr><td>DataSet 读取</td><td style="text-align:right;">367.09 ms</td><td style="text-align:right;">368.06 ms</td></tr><tr><td>补读</td><td style="text-align:right;">8.50 ms</td><td style="text-align:right;">8.67 ms</td></tr><tr><td>DataSet 数</td><td style="text-align:right;">34</td><td style="text-align:right;">34</td></tr><tr><td>批读覆盖</td><td style="text-align:right;">4480</td><td style="text-align:right;">4480</td></tr><tr><td>补读点数</td><td style="text-align:right;">62</td><td style="text-align:right;">62</td></tr><tr><td>失败点数</td><td style="text-align:right;">0</td><td style="text-align:right;">0</td></tr><tr><td>MMS 读值请求</td><td style="text-align:right;">96</td><td style="text-align:right;">96</td></tr></tbody></table><p>425 个异常回退全部消除。11 个代表性告警、整型状态和模拟量主值与单点读取逐一对比通过。 现场原进程的 21.25 秒和隔离服务的测量不是同进程严格 A/B，不能把全部耗时差都归因于单一因素。</p><p>回归验证：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>python -m pytest tests/protocols/iec61850/datasets tests/protocols/iec61850/model tests/protocols/iec61850/mms/test_read.py -q</span></span>
<span class="line"><span>161 passed, 25 skipped</span></span>
<span class="line"><span>ruff check &lt;修改的 Python 文件&gt;</span></span>
<span class="line"><span>All checks passed</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><h2 id="生效方式" tabindex="-1">生效方式 <a class="header-anchor" href="#生效方式" aria-label="Permalink to &quot;生效方式&quot;">​</a></h2><p>更新后重启后端，并对客户端执行“重新发现”，替换旧缓存的 FC 和字段顺序。 单纯复用旧模型缓存不能修正历史元数据。本次排查没有重启或修改正在使用的服务实例， 实测使用独立临时端口，完成后已销毁临时服务。</p>`,18)])])}const m=e(l,[["render",d]]);export{g as __pageData,m as default};
